package com.mockarena.question.api;
import com.fasterxml.jackson.databind.JsonNode; import com.mockarena.question.application.QuestionEvaluationDataService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/internal/v1/question-versions") public class QuestionEvaluationController {private final QuestionEvaluationDataService service;public QuestionEvaluationController(QuestionEvaluationDataService s){service=s;}@PostMapping("/evaluation-data") public Response data(@Valid @RequestBody Request r){return new Response(service.resolve(r.questionVersionIds()).stream().map(x->new Entry(x.questionVersionId(),x.questionTypeCode(),x.correctOptionId(),x.scoringPolicy())).toList());}public record Request(@NotEmpty List<UUID> questionVersionIds){} public record Entry(UUID questionVersionId,String questionTypeCode,String correctOptionId,JsonNode scoringPolicy){} public record Response(List<Entry> entries){}}
